var a={en:`200 units are on sale, but 20,000 shoppers try checkout within one minute. Database locks and timeouts surge.`,ua:`У продажу 200 одиниць, але 20 000 покупців запускають checkout за хвилину. Блокування БД і таймаути зростають.`};var t={en:[`Separate cached availability previews from authoritative reservation.`,`Compare serial queue, optimistic versioning and locks.`,`Design reservation expiry and concurrency stress tests.`],ua:[`Відокрем кешований показ наявності від авторитетного резерву.`,`Порівняй послідовну чергу, версіонування та блокування.`,`Спроєктуй закінчення резервів і стрес-тести.`]};var i=[{en:`Confirmed units never exceed 200.`,ua:`Підтверджених одиниць не більше 200.`},{en:`Failed or expired reservations release stock at most once.`,ua:`Невдалі чи прострочені резерви звільняють товар не більше одного разу.`}];var r={scenario:a,tasks:t,checks:i};export{i as checks,r as default,a as scenario,t as tasks};